package net.civeira.phylax.features.oauth.consent.application;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationChallege;
import net.civeira.phylax.features.oauth.consent.domain.ScopePermission;
import net.civeira.phylax.features.oauth.consent.domain.gateway.ScopeApprovalGateway;

/**
 * Application service for scope approval flows.
 *
 * <p>
 * Determines which requested scopes still need the user's explicit approval (mandatory or
 * optional), and stores the user's decision after the approval form is submitted.
 *
 * <p>
 * Delegates persistence and business logic to {@link ScopeApprovalGateway}.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ScopeApprovalUsecase {

  private final ScopeApprovalGateway gateway;

  /**
   * Returns the scopes that require explicit user approval.
   *
   * <p>
   * Normalizes the raw scope string before forwarding to the gateway. Returns an empty list when no
   * approval is needed.
   *
   * @param tenant tenant identifier
   * @param username authenticated username
   * @param clientId OAuth client identifier
   * @param scopeString raw scope string from the authorization request
   * @param completedChallenges challenges already satisfied in this authentication flow
   * @return pending scopes requiring approval; empty list if none
   */
  public List<ScopePermission> pendingApprovals(String tenant, String username, String clientId,
      String scopeString, List<AuthenticationChallege> completedChallenges) {
    List<String> scopes = normalizeScopes(scopeString);
    return gateway.pendingApprovals(tenant, username, clientId, scopes, completedChallenges);
  }

  /**
   * Persists the scopes accepted by the user.
   *
   * @param tenant tenant identifier
   * @param username authenticated username
   * @param clientId OAuth client identifier
   * @param acceptedScopes scopes explicitly accepted by the user
   */
  public void storeApprovedScopes(String tenant, String username, String clientId,
      List<String> acceptedScopes) {
    gateway.storeApprovedScopes(tenant, username, clientId, acceptedScopes);
  }

  private List<String> normalizeScopes(String scopeString) {
    if (null == scopeString || scopeString.isBlank()) {
      return List.of();
    }
    return Arrays.stream(scopeString.split("\\s+")).filter(s -> !s.isBlank()).distinct()
        .collect(Collectors.toList());
  }
}
